import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

import { defineConfig } from 'vite';
import { extensions, classicEmberSupport, ember } from '@embroider/vite';
import { babel } from '@rollup/plugin-babel';
import docfy from '@docfy/ember-vite';

const root = dirname(fileURLToPath(import.meta.url));
const GENERATED_PAGES = resolve(root, 'app/templates/docs');
const DOCFY_OVERRIDES = resolve(root, 'app/docfy-overrides.js');

/**
 * Pages generated by @docfy/ember-vite import `DocfyDemo` (and the other
 * docfy components) from '@docfy/ember'. Point those pages at a module that
 * re-exports '@docfy/ember' with the site's EUI-styled DocfyDemo instead.
 */
function siteDocfyComponents() {
  return {
    name: 'site-docfy-components',
    enforce: 'pre',
    resolveId(id, importer) {
      if (id === '@docfy/ember' && importer?.startsWith(GENERATED_PAGES)) {
        return DOCFY_OVERRIDES;
      }
    },
  };
}

export default defineConfig({
  plugins: [
    docfy({ root }),
    siteDocfyComponents(),
    classicEmberSupport(),
    ember(),
    babel({
      babelHelpers: 'runtime',
      extensions,
    }),
  ],
});
